static void lm_PosixSystem_catchTermination_2000030(void) {
    struct sigaction a;
    memset(&a, 0, sizeof a);
    a.sa_handler = lm_os_on_signal;
    sigemptyset(&a.sa_mask);
    sigaction(SIGINT, &a, NULL);
    sigaction(SIGTERM, &a, NULL);
}
#endif
